function [A,A0,T] = inwardTotalArea(DT)
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Given a Delaunay Triangulation object DT, this routine
% computes for each vertex p, the area of the (unique) neigboring 
% triangle in the triangulation whose projection from p contains the 
% center of mass of the vertices. 
%
% Output: 
%   A   : total area of the triangles described above
%   A0  : area of the (unique) triangle containing the center of mass
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

P = DT.Points;
N = size(P, 1);
cx = mean(P(:,1));
cy = mean(P(:,2));

com_triangle = pointLocation(DT,cx,cy); % triangle containg center of mass
com_triangle_verts = DT.ConnectivityList(com_triangle,:);
com_triangle_coords = DT.Points(com_triangle_verts',:);
A0 = 1/2*abs(det( [com_triangle_coords ones(3,1)] ));

angles2com = atan2(cy-P(:,2), cx-P(:,1));

VA = vertexAttachments(DT);
T = zeros(3,2,N);
A = 0;
for i = 1:N
    tri_idx = VA{i}';           % get IDs of m triangles containing i
    tris = DT.ConnectivityList(tri_idx,:);  % get vertices of those triangles (m x 3 array)
    verts = unique(tris);       % list those vertices (without repeats)
    verts = verts(verts~=i);    % exclude i itself
    pts = P(verts,:);   % get the coords of those vertices
    angs = atan2(pts(:,2)-P(i,2),pts(:,1)-P(i,1));  % get their angle from i
    [~,I] = sort( [angles2com(i); angs] );    % sort these verts AND the COM by angle
    pts_com = [ cx cy ; pts ];
    pts_com = pts_com(I,:);
    k = find(I==1);             % get position of COM after sorting
    pts_com = circshift(pts_com, 2-k, 1);

    T(:,:,i) = [ P(i,:) ; pts_com(1,:) ; pts_com(3,:) ];  
    A = A + 1/2*abs(det( [ P(i,:) 1 ; pts_com(1,:) 1 ; pts_com(3,:) 1 ] ));
end

A = A - 2*A0;

% hold on
% triplot(DT);
% for i = 1:N
%     fill(T(:,1,i), T(:,2,i), 'b', 'FaceAlpha', '0.2');
% end
% scatter([cx], [cy],'red');
% text(x,y,num2cell(1:N));
end

nearestOnSegment.m:
function y = nearestOnSegment(S,x)

arguments
    S (2,2) double
    x (2,1) double
end

p = S(:,1);
q = S(:,2);
a = -atan2(p(2)-q(2),p(1)-q(1));

R = [ cos(a) -sin(a); sin(a) cos(a) ];

X = R*[p q x];

while true
    [~,j] = min(X(1,1:2));
    if X(1,3) <= X(1,j)
        y0 = X(:,j);
        break;
    end

    [~,j] = max(X(1,1:2));
    if X(1,3) >= X(1,j)
        y0 = X(:,j);
        break;
    end

    y0 = [ X(1,3); X(2,1) ];
    break;
end

y = R'*y0;

end

neighborhoods.m:
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% NEIGHBORHOODS
% Get graph neighborhoods of vertices of Delaunay Triangulation
%
% Syntax:
%   [nbhd,nearest,dist] = neighborhoods(DT)
%   [nbhd,nearest,dist] = neighborhoods(DT,r)
% Input:
%   DT  :   delaunayTriangulation object
%   r   :   positive integer or Inf. topological radius of each
%           neighborhood. Default 1.
% Output:
%   nbhd:   Nx1 cell array where N is the number of points in DT. nbhd{i}
%           is a row vector containing the indices of points in DT
%           reachable from point i via a walk in DT of length at most r
%           excluding i itself.
%   nearest: Nx1 double. nearest(i) is the index of the vertex in DT
%           distinct from i which is closest to i.
%   dist:   Nx1 double. dist(i) is the distance between vertex i and its
%           nearest neighbor in DT.


function [nbhd,nearest,dist] = neighborhoods(DT,r)

arguments
    DT delaunayTriangulation
    r  (1,1) double {mustBePositiveIntegerOrInf} = 1
end

X = DT.Points;
N = size(X,1);
if r==Inf, r=N; end
E = edges(DT);
EE = [ E ; E(:,[2 1]) ];
v = ones(size(EE,1),1);
adj = sparse(EE(:,1),EE(:,2),v);
nbhd = cell(N,r);
nearest = zeros(N,1);
dist = zeros(N,1);
for i=1:N
    neighbors = find(adj(i,:)==1);
    [d,l] = min(arrayfun(@(j) norm(X(i,:)-X(j,:)), neighbors));
    dist(i) = d;
    nearest(i) = neighbors(l);
    nbhd{i,1} = neighbors;
end

neye = ones(N,N)-eye(N);  % false diagonal, true off-diagonal

if r > 1
    powAdj = eye(N);
    cumAdj = zeros(N,N);
    for k=1:r
        powAdj = powAdj*adj;
        cumAdj = cumAdj+powAdj;
        cumAdj = cumAdj & neye;
        for i=1:N
            nbhd{i,k} = find(cumAdj(i,:)~=0);
        end
        cumAdj = cumAdj | eye(N);
        if all(cumAdj,'all')
            break;
        end
    end
end

end

% validation
function mustBePositiveIntegerOrInf(a)
    if ~((a==floor(a) && a>0) || a==Inf)
        eid = 'neighborhoods:inputError';
        msg = 'Radius must be a positive integer or Inf';
        throwAsCaller(MException(eid,msg));
    end
end

