function [energy,A] = poly_area_energy( x, y) 

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% This function computes the centroid coordinates of a Voronoi region as
% well as its individual Voronoi energy
%
% INPUT: - x,y are the coordinates of the vertices of the Voronoi cell
%        - genx, geny are the coordinates of the generator of the cell.
%    
% OUTPUT: - centroid is a list containg the coordinates of centroid
%           of the cell (x_cen and y_cen).
%         - energy is the individual energy of the Voronoi cell
%
% Initially written by H.J. Sommer III - 16.12.09 - tested under MATLAB v9.0
% Modified by Ivan Gonzalez @McGill University 
% Last update: May 17th of 2018.
%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

% check if inputs are same size
if ~isequal( size(x), size(y) )
  error( 'X and Y must be the same size');
end

% We shift the vertices by [genx;geny] to compute quantities with respect
% to the generator and not the origin of the domain.
x = x - mean(x);
y = y - mean(y);

% summations for CCW boundary. Direct application of Green's theorem to
% compute quntities over the polygon
xp = x( [2:end 1] );
yp = y( [2:end 1] );
a = x.*yp - xp.*y;

b=sqrt((x-xp).^2+(y-yp).^2);
P=sum(b); % positive perimeter

A = sum( a ) /2;
xc = sum( (x+xp).*a  ) /6/A;
yc = sum( (y+yp).*a  ) /6/A;
Ixx = sum( (y.*y +y.*yp + yp.*yp).*a  ) /12;
Iyy = sum( (x.*x +x.*xp + xp.*xp).*a  ) /12;

A=abs(A);

% In case we have a CW order we change the sigh

Ixx=abs(Ixx); Iyy=abs(Iyy);
energy=Ixx+Iyy;


end

rayPolylineIntersect.m:
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% RAYPOLYLINEINTERSECT
% Drop-in replacement for the single intersection point that
% voronoiProjectToBoundary.m needs from polyxpoly, without requiring
% the Mapping Toolbox.
%
% Finds the intersection of the ray from (rayx(1),rayy(1)) through
% (rayx(2),rayy(2)) with the polyline defined by (px,py), restricted to
% the segment t in [0,1] along the ray (i.e. only intersections between
% the ray's two given endpoints, same convention polyxpoly uses here
% since the ray is drawn out to a point L units away, far outside the
% bounding box).
%
% Returns the single closest intersection point (xi,yi) to the ray's
% start point. If no intersection is found, returns (NaN,NaN).

function [xi,yi] = rayPolylineIntersect(rayx, rayy, px, py)

xi = NaN; yi = NaN;
best_t = Inf;

x1 = rayx(1); y1 = rayy(1);
x2 = rayx(2); y2 = rayy(2);
rdx = x2 - x1;
rdy = y2 - y1;

n = numel(px);
for k = 1:(n-1)
    x3 = px(k);   y3 = py(k);
    x4 = px(k+1); y4 = py(k+1);

    sdx = x4 - x3;
    sdy = y4 - y3;

    denom = rdx*sdy - rdy*sdx;
    if abs(denom) < 1e-12
        continue;  % parallel (or degenerate) segment, skip
    end

    t = ((x3-x1)*sdy - (y3-y1)*sdx) / denom;
    u = ((x3-x1)*rdy - (y3-y1)*rdx) / denom;

    if t >= -1e-9 && t <= 1+1e-9 && u >= -1e-9 && u <= 1+1e-9
        if t < best_t
            best_t = t;
            xi = x1 + t*rdx;
            yi = y1 + t*rdy;
        end
    end
end

end

